using Framework.Parameters;
using Game.AI.Parameters;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// 敵AIの聴覚パラメーターを検証する。
    /// </summary>
    public sealed class MazeEnemyHearingParameterTest
        : MonoBehaviour
    {
        [Header("テスト設定")]

        [SerializeField]
        [Tooltip("開始時にテストを実行する。")]
        private bool runTestsOnStart = true;

        /// <summary>
        /// 成功したテスト数。
        /// </summary>
        private int passedCount;

        /// <summary>
        /// 失敗したテスト数。
        /// </summary>
        private int failedCount;

        /// <summary>
        /// 開始時にテストを実行する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("Run Tests")]
        public void RunTests()
        {
            passedCount = 0;
            failedCount = 0;

            Debug.Log(
                "===== 聴覚パラメーターテスト開始 =====",
                this);

            TestCatalog();
            TestDefaultParameterSet();
            TestProfile();
            TestRuntimeParameters();

            Debug.Log(
                $"===== テスト終了：成功 {passedCount}件 / " +
                $"失敗 {failedCount}件 =====",
                this);
        }

        /// <summary>
        /// 共通パラメーター定義を検証する。
        /// </summary>
        private void TestCatalog()
        {
            bool correctCount =
                MazeEnemyParameterCatalog.Count == 19;

            Debug.Assert(
                correctCount,
                "パラメーター定義数", this);
            Check(correctCount,
                "パラメーター定義数");

            bool correctIds =
                (int)MazeEnemyParameter.HearingRange == 203 &&
                (int)MazeEnemyParameter.HearingSensitivity == 204 &&
                (int)MazeEnemyParameter.HearingAccuracy == 205;

            Debug.Assert(
                correctIds,
                "聴覚パラメーター識別子", this);
            Check(correctIds,
                "聴覚パラメーター識別子");

            bool hasRange =
                MazeEnemyParameterCatalog.Contains(
                    MazeEnemyParameter.HearingRange);

            Debug.Assert(
                hasRange,
                "聴覚範囲の登録", this);
            Check(hasRange,
                "聴覚範囲の登録");

            bool hasSensitivity =
                MazeEnemyParameterCatalog.Contains(
                    MazeEnemyParameter.HearingSensitivity);

            Debug.Assert(
                hasSensitivity,
                "聴覚感度の登録", this);
            Check(hasSensitivity,
                "聴覚感度の登録");

            bool hasAccuracy =
                MazeEnemyParameterCatalog.Contains(
                    MazeEnemyParameter.HearingAccuracy);

            Debug.Assert(
                hasAccuracy,
                "聴覚精度の登録", this);
            Check(hasAccuracy,
                "聴覚精度の登録");

            var range =
                MazeEnemyParameterCatalog.GetDefinition(
                    MazeEnemyParameter.HearingRange);

            bool correctRange =
                range.DefaultValue == 8f &&
                range.MinValue == 0f &&
                range.MaxValue == 64f;

            Debug.Assert(
                correctRange,
                "聴覚範囲の定義値", this);
            Check(correctRange,
                "聴覚範囲の定義値");

            var sensitivity =
                MazeEnemyParameterCatalog.GetDefinition(
                    MazeEnemyParameter.HearingSensitivity);

            bool correctSensitivity =
                sensitivity.DefaultValue == 0.5f &&
                sensitivity.MinValue == 0f &&
                sensitivity.MaxValue == 1f;

            Debug.Assert(
                correctSensitivity,
                "聴覚感度の定義値", this);
            Check(correctSensitivity,
                "聴覚感度の定義値");

            var accuracy =
                MazeEnemyParameterCatalog.GetDefinition(
                    MazeEnemyParameter.HearingAccuracy);

            bool correctAccuracy =
                accuracy.DefaultValue == 0.5f &&
                accuracy.MinValue == 0f &&
                accuracy.MaxValue == 1f;

            Debug.Assert(
                correctAccuracy,
                "聴覚精度の定義値", this);
            Check(correctAccuracy,
                "聴覚精度の定義値");
        }

        /// <summary>
        /// 標準パラメーターセットを検証する。
        /// </summary>
        private void TestDefaultParameterSet()
        {
            using (var parameters =
                MazeEnemyParameterCatalog.CreateParameterSet())
            {
                Debug.Assert(
                    parameters.Count == 19,
                    "標準パラメーター数", this);
                Check(parameters.Count == 19,
                    "標準パラメーター数");

                float range = parameters.GetValue(
                    MazeEnemyParameter.HearingRange);

                Debug.Assert(
                    range == 8f,
                    "標準聴覚範囲", this);
                Check(range == 8f,
                    "標準聴覚範囲");

                float sensitivity = parameters.GetValue(
                    MazeEnemyParameter.HearingSensitivity);

                Debug.Assert(
                    sensitivity == 0.5f,
                    "標準聴覚感度", this);
                Check(sensitivity == 0.5f,
                    "標準聴覚感度");

                float accuracy = parameters.GetValue(
                    MazeEnemyParameter.HearingAccuracy);

                Debug.Assert(
                    accuracy == 0.5f,
                    "標準聴覚精度", this);
                Check(accuracy == 0.5f,
                    "標準聴覚精度");

                float moveSpeed = parameters.GetValue(
                    MazeEnemyParameter.MoveSpeed);

                Debug.Assert(
                    moveSpeed == 3.5f,
                    "既存移動速度の維持", this);
                Check(moveSpeed == 3.5f,
                    "既存移動速度の維持");

                float detectionRange = parameters.GetValue(
                    MazeEnemyParameter.DetectionRange);

                Debug.Assert(
                    detectionRange == 6f,
                    "既存視覚範囲の維持", this);
                Check(detectionRange == 6f,
                    "既存視覚範囲の維持");
            }
        }

        /// <summary>
        /// プロファイルからの生成を検証する。
        /// </summary>
        private void TestProfile()
        {
            var profile =
                ScriptableObject.CreateInstance<MazeEnemyProfile>();

            try
            {
                float range = profile.GetInitialValue(
                    MazeEnemyParameter.HearingRange);

                Debug.Assert(
                    range == 8f,
                    "プロファイルの聴覚範囲", this);
                Check(range == 8f,
                    "プロファイルの聴覚範囲");

                float sensitivity = profile.GetInitialValue(
                    MazeEnemyParameter.HearingSensitivity);

                Debug.Assert(
                    sensitivity == 0.5f,
                    "プロファイルの聴覚感度", this);
                Check(sensitivity == 0.5f,
                    "プロファイルの聴覚感度");

                float accuracy = profile.GetInitialValue(
                    MazeEnemyParameter.HearingAccuracy);

                Debug.Assert(
                    accuracy == 0.5f,
                    "プロファイルの聴覚精度", this);
                Check(accuracy == 0.5f,
                    "プロファイルの聴覚精度");

                using (var first = profile.CreateParameterSet())
                using (var second = profile.CreateParameterSet())
                {
                    Debug.Assert(
                        first.Count == 19,
                        "プロファイルの生成数", this);
                    Check(first.Count == 19,
                        "プロファイルの生成数");

                    bool correctValues =
                        first.GetValue(
                            MazeEnemyParameter.HearingRange) == range &&
                        first.GetValue(
                            MazeEnemyParameter.HearingSensitivity) ==
                                sensitivity &&
                        first.GetValue(
                            MazeEnemyParameter.HearingAccuracy) ==
                                accuracy;

                    Debug.Assert(
                        correctValues,
                        "聴覚初期値の反映", this);
                    Check(correctValues,
                        "聴覚初期値の反映");

                    // 一方の実行時能力だけを変更する。
                    first.SetBaseValue(
                        MazeEnemyParameter.HearingRange,
                        20f);

                    bool independent =
                        first.GetValue(
                            MazeEnemyParameter.HearingRange) == 20f &&
                        second.GetValue(
                            MazeEnemyParameter.HearingRange) == 8f;

                    Debug.Assert(
                        independent,
                        "個体ごとの聴覚能力の独立性", this);
                    Check(independent,
                        "個体ごとの聴覚能力の独立性");

                    bool profileUnchanged =
                        profile.GetInitialValue(
                            MazeEnemyParameter.HearingRange) == 8f;

                    Debug.Assert(
                        profileUnchanged,
                        "プロファイル初期値の維持", this);
                    Check(profileUnchanged,
                        "プロファイル初期値の維持");
                }
            }
            finally
            {
                // テスト用の一時アセットを解放する。
                if (Application.isPlaying)
                {
                    Destroy(profile);
                }
                else
                {
                    DestroyImmediate(profile);
                }
            }
        }

        /// <summary>
        /// 実行時の聴覚能力変更を検証する。
        /// </summary>
        private void TestRuntimeParameters()
        {
            using (var parameters =
                MazeEnemyParameterCatalog.CreateParameterSet())
            {
                var rangeId =
                    MazeEnemyParameter.HearingRange;

                var sensitivityId =
                    MazeEnemyParameter.HearingSensitivity;

                var accuracyId =
                    MazeEnemyParameter.HearingAccuracy;

                parameters.SetBaseValue(rangeId, 12f);

                bool changed =
                    parameters.GetValue(rangeId) == 12f;

                Debug.Assert(
                    changed,
                    "実行時の聴覚範囲変更", this);
                Check(changed,
                    "実行時の聴覚範囲変更");

                parameters.SetBaseValue(rangeId, -5f);

                bool minimum =
                    parameters.GetValue(rangeId) == 0f;

                Debug.Assert(
                    minimum,
                    "聴覚範囲の下限補正", this);
                Check(minimum,
                    "聴覚範囲の下限補正");

                parameters.SetBaseValue(rangeId, 100f);

                bool maximum =
                    parameters.GetValue(rangeId) == 64f;

                Debug.Assert(
                    maximum,
                    "聴覚範囲の上限補正", this);
                Check(maximum,
                    "聴覚範囲の上限補正");

                parameters.SetBaseValue(sensitivityId, -1f);

                bool sensitivityMin =
                    parameters.GetValue(sensitivityId) == 0f;

                Debug.Assert(
                    sensitivityMin,
                    "聴覚感度の下限補正", this);
                Check(sensitivityMin,
                    "聴覚感度の下限補正");

                parameters.SetBaseValue(sensitivityId, 2f);

                bool sensitivityMax =
                    parameters.GetValue(sensitivityId) == 1f;

                Debug.Assert(
                    sensitivityMax,
                    "聴覚感度の上限補正", this);
                Check(sensitivityMax,
                    "聴覚感度の上限補正");

                parameters.SetBaseValue(accuracyId, -1f);

                bool accuracyMin =
                    parameters.GetValue(accuracyId) == 0f;

                Debug.Assert(
                    accuracyMin,
                    "聴覚精度の下限補正", this);
                Check(accuracyMin,
                    "聴覚精度の下限補正");

                parameters.SetBaseValue(accuracyId, 2f);

                bool accuracyMax =
                    parameters.GetValue(accuracyId) == 1f;

                Debug.Assert(
                    accuracyMax,
                    "聴覚精度の上限補正", this);
                Check(accuracyMax,
                    "聴覚精度の上限補正");

                parameters.ResetAll();

                bool reset =
                    parameters.GetValue(rangeId) == 8f &&
                    parameters.GetValue(sensitivityId) == 0.5f &&
                    parameters.GetValue(accuracyId) == 0.5f;

                Debug.Assert(
                    reset,
                    "聴覚能力の初期化", this);
                Check(reset,
                    "聴覚能力の初期化");

                // 聴覚範囲を一時的に強化する。
                var modifier =
                    ParameterModifier.CreateAdditive(4f);

                parameters.TryAddModifier(
                    rangeId, modifier);

                bool modified =
                    parameters.GetValue(rangeId) == 12f;

                Debug.Assert(
                    modified,
                    "聴覚範囲へのModifier適用", this);
                Check(modified,
                    "聴覚範囲へのModifier適用");

                parameters.TryRemoveModifier(
                    rangeId, modifier.Id);

                bool removed =
                    parameters.GetValue(rangeId) == 8f;

                Debug.Assert(
                    removed,
                    "聴覚Modifierの解除", this);
                Check(removed,
                    "聴覚Modifierの解除");
            }
        }

        /// <summary>
        /// テスト結果を集計して出力する。
        /// </summary>
        /// <param name="condition">検証結果</param>
        /// <param name="testName">テスト名</param>
        private void Check(
            bool condition,
            string testName)
        {
            if (condition)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】 {testName}",
                    this);
            }
        }
    }
}
